functions.lexer_getchar:
int lexer_getchar(Lexer *l)
{
    l->position++;
    l->last_column = l->column;
    l->buffer[0] = getc(l->fp);
    if (l->buffer[0] == '\n')
    {
        l->line++;
        l->column = 0;
    }
    else
    {
        l->column++;
    }
    return l->buffer[0];
}

