int lex(Lexer *l, Token *t)
{
    for (;;)
    {
        real_lex(l, t);
        if (t->type != TT_NEWLINE)
            break;
    }
    return 0;
}

functions.real_lex:
int real_lex(Lexer *l, Token *t)
{
    if (l->unlexed_count > 0)
    {
        l->unlexed_count--;
        memcpy(t, &l->unlexed[l->unlexed_count], sizeof(Token));
        return 0;
    }
    skip_to_token(l);
    int init = lexer_getchar(l);
    memset(t->contents, 0, 256);
    memcpy(t->source_file, &l->current_file, 256);
    static char eof[] = "[end of file]";
    if (init == (-1))
    {
        strcpy(t->contents, eof);
        t->length = strlen(eof);
        t->type = TT_EOF;
        t->line = l->line;
        t->column = l->column;
        return 0;
    }
    if (init == ' ' || init == '\t')
    {
        do
        {
            fprintf(stderr, "\033[%dm", 31);
            fprintf(stderr, "Error: jccc: "
                            "internal error: did not skip whitespace correctly"
                            "\n");
            fprintf(stderr, "\033[0m");
        } while (0);
        return -1;
    }
    static char nline[] = "[newline]";
    if (init == '\n')
    {
        strcpy(t->contents, nline);
        t->length = strlen(nline);
        t->type = TT_NEWLINE;
        t->line = l->line;
        t->column = l->column;
        return 0;
    }
    int pos = 0;
    t->contents[pos++] = init;
    if (in_string(init, single_char_tokens))
    {
        t->length = pos;
        t->type = ttype_one_char(init);
        t->line = l->line;
        t->column = l->column;
        return 0;
    }
    int c;
    int starting_line;
    int starting_col;
    if (is_valid_numeric_or_id_char(init))
    {
        starting_line = l->line;
        starting_col = l->column;
        for (;;)
        {
            c = lexer_getchar(l);
            if (!is_valid_numeric_or_id_char(c))
                break;
            if (pos >= 256 - 1)
            {
                do
                {
                    fprintf(stderr, "\033[%dm", 31);
                    fprintf(stderr,
                            "Error: jccc: "
                            "identifier too long, over %d characters"
                            "\n",
                            256);
                    fprintf(stderr, "\033[0m");
                } while (0);
                do
                {
                    fprintf(stderr, "\033[%dm", 31);
                    fprintf(stderr, "Error: jccc: "
                                    "identifier began with the following:"
                                    "\n");
                    fprintf(stderr, "\033[0m");
                } while (0);
                do
                {
                    fprintf(stderr, "\033[%dm", 31);
                    fprintf(stderr,
                            "Error: jccc: "
                            "%.*s"
                            "\n",
                            256, t->contents);
                    fprintf(stderr, "\033[0m");
                } while (0);
                return -1;
            }
            t->contents[pos++] = c;
        }
        lexer_ungetchar(l);
        t->contents[pos] = '\0';
        t->type = ttype_many_chars(t->contents);
        t->length = pos;
        t->line = starting_line;
        t->column = starting_col;
        return 0;
    }
    if (starts_operator(init))
    {
        while (valid_operator_sequence(t->contents))
        {
            t->contents[pos++] = (c = lexer_getchar(l));
        }
        lexer_ungetchar(l);
        t->contents[pos - 1] = '\0';
        t->type = ttype_from_string(t->contents);
        t->length = pos;
        return 0;
    }
    do
    {
        fprintf(stderr, "\033[%dm", 31);
        fprintf(stderr,
                "Error: jccc: "
                "lexer unable to identify token starting with: %c"
                "\n",
                init);
        fprintf(stderr, "\033[0m");
    } while (0);
    return 0;
}

functions.unlex:
int unlex(Lexer *l, Token *t)
{
    if (l->unlexed_count >= 5)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 31);
            fprintf(stderr,
                    "Error: jccc: "
                    "internal: tried to unlex more than %d tokens at a time"
                    "\n",
                    5);
            fprintf(stderr, "\033[0m");
        } while (0);
        return -1;
    }
    memcpy(&l->unlexed[l->unlexed_count], t, sizeof(Token));
    l->unlexed_count++;
    return 0;
}

functions.skip_to_token:
int skip_to_token(Lexer *l)
{
    char cur, prev;
    int in_block = 0, pass = 0;
    if ((cur = lexer_getchar(l)) != (-1))
    {
        prev = cur;
        if (!(cur == ' ' || cur == '\t' || cur == '/'))
        {
            lexer_ungetchar(l);
            return 0;
        }
    }
    else
    {
        return -1;
    }
    while ((cur = lexer_getchar(l)) != (-1))
    {
        if (cur == '/' && prev == '/' && in_block == 0)
        {
            in_block = 1;
        }
        else if (cur == '*' && prev == '/' && in_block == 0)
        {
            in_block = 2;
            pass = 2;
        }
        else if ((in_block == 1 && cur == '\n') || (in_block == 2 && cur == '/' && prev == '*' && pass <= 0))
        {
            in_block = 0;
        }
        else if (prev == '/' && !(cur == '*' || cur == '/') && in_block == 0)
        {
            lexer_ungetchar(l);
            return 0;
        }
        if (!(cur == ' ' || cur == '\t' || cur == '/') && in_block == 0)
        {
            lexer_ungetchar(l);
            return 0;
        }
        pass -= 1;
        prev = cur;
    }
    return -1;
}

functions.ttype_one_char:
TokenType ttype_one_char(char c)
{
    switch (c)
    {
    case '(':
        return TT_OPAREN;
    case ')':
        return TT_CPAREN;
    case '{':
        return TT_OBRACE;
    case '}':
        return TT_CBRACE;
    case '[':
        return TT_OBRACKET;
    case ']':
        return TT_CBRACKET;
    case ';':
        return TT_SEMI;
    case '.':
        return TT_PERIOD;
    case ',':
        return TT_COMMA;
    case '-':
        return TT_MINUS;
    case '+':
        return TT_PLUS;
    case '*':
        return TT_STAR;
    case '/':
        return TT_SLASH;
    case '=':
        return TT_ASSIGN;
    case ':':
        return TT_COLON;
    case '%':
        return TT_MOD;
    case '&':
        return TT_BAND;
    case '|':
        return TT_BOR;
    case '>':
        return TT_GREATER;
    case '<':
        return TT_LESS;
    case '!':
        return TT_LNOT;
    case '~':
        return TT_BNOT;
    case '^':
        return TT_XOR;
    case '#':
        return TT_POUND;
    case '?':
        return TT_QMARK;
    default:
        if (((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit))
        {
            return TT_LITERAL;
        }
        else
        {
            return TT_IDENTIFIER;
        }
    }
}

