functions.lfind_index:
static int lfind_index(List *l, ListBlock **lb, int *i)
{
    *lb = l->head;
    if (*i < 0)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 31);
            fprintf(stderr,
                    "Error: jccc: "
                    "internal: list index was negative (%d)"
                    "\n",
                    *i);
            fprintf(stderr, "\033[0m");
        } while (0);
        return -1;
    }
    while (*i >= (*lb)->size)
    {
        if (lb)
        {
            *lb = (*lb)->next;
            *i -= (*lb)->size;
        }
        else
        {
            do
            {
                fprintf(stderr, "\033[%dm", 31);
                fprintf(stderr,
                        "Error: jccc: "
                        "internal: list index %d out of bounds"
                        "\n",
                        *i);
                fprintf(stderr, "\033[0m");
            } while (0);
            return -1;
        }
    }
    return 0;
}

