functions.ladd_element:
int ladd_element(List *l, void *element)
{
    if (l->head == ((void *)0))
    {
        l->tail = new_block(l);
        l->head = l->tail;
    }
    ListBlock *lb = l->tail;
    if (lb->full < lb->size)
    {
        lb->array[lb->full++] = element;
    }
    else
    {
        l->tail = new_block(l);
        lb->next = l->tail;
        lb = lb->next;
        lb->array[lb->full++] = element;
    }
    return 0;
}

functions.literate:
int literate(List *l, int (*fn)(void *))
{
    ListBlock *lb = l->head;
    int acc = 0;
    while (lb != ((void *)0))
    {
        for (int i = 0; i < lb->full; ++i)
        {
            acc += fn(lb->array[i]);
        }
        lb = lb->next;
    }
    return acc;
}

