functions.parse:
int parse(const char *filename)
{
    Lexer lexer;
    FILE *fp = fopen(filename, "r");
    if (!fp)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 31);
            fprintf(stderr,
                    "Error: jccc: "
                    "File %s not found"
                    "\n",
                    filename);
            fprintf(stderr, "\033[0m");
        } while (0);
        return 1;
    }
    lexer.fp = fp;
    lexer.unlexed_count = 0;
    lexer.column = lexer.line = 1;
    Token t;
    int i = 0;
    int buffer_size = 16;
    Token *tokens = calloc(buffer_size, sizeof(Token));
    do
    {
        if (lex(&lexer, &t))
        {
            return 1;
        }
        if (buffer_size <= i)
        {
            buffer_size *= 2;
            tokens = calloc(buffer_size, sizeof(Token));
        }
        tokens[i] = t;
        printf("Contents: %20s, type: %20s, position: %d/%d\n", t.contents, ttype_name(t.type), t.line, t.column);
        i++;
    } while (t.type != TT_EOF);
    if (tokens[0].type == TT_INT && tokens[1].type == TT_IDENTIFIER && (strcmp(tokens[1].contents, "main") == 0))
    {
        if (tokens[2].type == TT_OPAREN && tokens[3].type == TT_CPAREN && tokens[4].type == TT_OBRACE)
        {
            if (tokens[5].type == TT_RETURN && tokens[6].type == TT_LITERAL &&
                ((*__ctype_b_loc())[(int)((tokens[6].contents[0]))] & (unsigned short int)_ISdigit) &&
                tokens[7].type == TT_SEMI)
            {
                if (tokens[8].type == TT_CBRACE)
                {
                    printf("\n");
                    char *code_start = start_main();
                    printf(code_start);
                    char *code_end = end_main_custom_return(atoi(tokens[6].contents));
                    printf(code_end);
                }
                else
                {
                    do
                    {
                        fprintf(stderr, "\033[%dm", 31);
                        fprintf(stderr, "Error: jccc: "
                                        "Wrong closing brace.\n"
                                        "\n");
                        fprintf(stderr, "\033[0m");
                    } while (0);
                }
            }
            else
            {
                do
                {
                    fprintf(stderr, "\033[%dm", 31);
                    fprintf(stderr, "Error: jccc: "
                                    "Return value is wrong.\n"
                                    "\n");
                    fprintf(stderr, "\033[0m");
                } while (0);
            }
        }
        else
        {
            do
            {
                fprintf(stderr, "\033[%dm", 31);
                fprintf(stderr, "Error: jccc: "
                                "Wrong main function body.\n"
                                "\n");
                fprintf(stderr, "\033[0m");
            } while (0);
        }
    }
    else
    {
        do
        {
            fprintf(stderr, "\033[%dm", 31);
            fprintf(stderr, "Error: jccc: "
                            "Not correct main function.\n"
                            "\n");
            fprintf(stderr, "\033[0m");
        } while (0);
    }
    fclose(fp);
    return 0;
}

