functions.main:
int main(int argc, char **argv)
{
    --argc, ++argv;
    if (argc == 0)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 37);
            fprintf(stderr, "jccc: "
                            "Usage: --token-dump <filename> to see all tokens"
                            "\n");
            fprintf(stderr, "\033[0m");
        } while (0);
        return 0;
    }
    if (argc == 1)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 37);
            fprintf(stderr,
                    "jccc: "
                    "default compilation not supported yet -- try 'jccc "
                    "--token-dump %s' instead."
                    "\n",
                    argv[0]);
            fprintf(stderr, "\033[0m");
        } while (0);
        return 1;
    }
    if (argc > 2)
    {
        do
        {
            fprintf(stderr, "\033[%dm", 37);
            fprintf(stderr, "jccc: "
                            "expected only two arguments!"
                            "\n");
            fprintf(stderr, "\033[0m");
        } while (0);
        return 1;
    }
    if (strcmp(argv[0], "--token-dump") == 0)
    {
        return lexer_dump(argv[1]);
    }
    else if (strcmp(argv[0], "--test-parse") == 0)
    {
        parse(argv[1]);
        return 0;
    }
    do
    {
        fprintf(stderr, "\033[%dm", 31);
        fprintf(stderr,
                "Error: jccc: "
                "option %s not recognized."
                "\n",
                argv[1]);
        fprintf(stderr, "\033[0m");
    } while (0);
    return 1;
}

